import numpy as np

def can_expand(n, s, N):
    grid = np.zeros((n, n), dtype=bool)
    grid[n//2, n//2] = True
    green_cells = [(n//2, n//2)]
    max_turns = 2000
    turns = 0
    while turns < max_turns:
        expanded = False
        for c in green_cells:
            cx, cy = c
            non_green = []
            half = N // 2
            for i in range(cx - half, cx + half + 1):
                for j in range(cy - half, cy + half + 1):
                    if 0 <= i < n and 0 <= j < n and not grid[i, j]:
                        non_green.append((i, j))
            if len(non_green) >= s:
                for i in range(s):
                    nx, ny = non_green[i]
                    grid[nx, ny] = True
                    green_cells.append((nx, ny))
                expanded = True
                turns += 1
                break
        if not expanded:
            break
    return np.sum(grid)

